"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import { useShortcutPlatform } from "../kbd/kbd";
import {
  useDeferredValue,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  useLayoutEffect,
} from "react";
import { AnimatePresence, motion } from "motion/react";
import { cn } from "../lib/cn";
import { duration, ease } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer } from "./chart-parts";
import { useDockedReadout, useInputSource } from "./chart-fit";
import { chartFocusClass, slotColor, useElementWidth, resolveInstructions, itemAt } from "./chart-utils";
import { ChartDockHint, ChartTip, defaultCompact, SequentialLegend, useEntrance } from "./heatmap";
import { ChartFigure } from "./chart-figure";
import {
  WORLD_FRAME_WIDTH,
  WORLD_FRAME_HEIGHT,
  hash,
  SPHERE_PATH,
  GRATICULE_PATH,
  useWorldShapes,
} from "./geo-map/projection";
import { useWorldMapKeyboard, useWorldMapPointer } from "./geo-map/interaction";
import { useWorldMapView } from "./geo-map/view";
import { MAP_RAMP_FLOOR, useWorldMapData } from "./geo-map/data";
import { defaultWorldMapLabels, type WorldMapDatum, type WorldMapProps } from "./geo-map/types";
import {
  LAND,
  divergingPosition,
  HatchPattern,
  NoDataKey,
  LegendRow,
  DivergingLegend,
  BubbleLegend,
  DOCK_BAND,
  isolate,
  cssEase,
  DockedReadout,
  Bubble,
  CountryLayer,
  useBandsEntrance,
} from "./geo-map/parts";

export {
  WORLD_FRAME_WIDTH,
  WORLD_FRAME_HEIGHT,
  projectWorld,
  loadWorld110m,
  worldCountryName,
} from "./geo-map/projection";
export {
  type WorldMapDatum,
  type WorldMapPoint,
  type WorldMapSelection,
  type WorldMapLabels,
  defaultWorldMapLabels,
  type WorldMapProps,
} from "./geo-map/types";
export { divergingColor } from "./geo-map/parts";
export { type WorldMapTableProps, WorldMapTable } from "./geo-map/table";

/* ======================================================================
 * WorldMap
 * ====================================================================== */

const NO_DATA: WorldMapDatum[] = [];

/**
 * World map: a choropleth (each country coloured on a sequential or diverging scale) or a bubble
 * map (circles sized by value at each country's centre, or at any longitude / latitude).
 *
 * - Equal Earth projection: areas are true to scale, so big countries don't overstate their value.
 * - Country names come from Intl in `locale`; values accept any ISO 3166-1 code.
 * - Hover or tap a country (or bubble) for a glass tooltip; it pins on touch. Focus the map and
 *   use the arrow keys to move between neighbouring countries, Page Up / Page Down by rank,
 *   or type a name.
 * - Zoom: buttons, ⌘/Ctrl + scroll or trackpad pinch, two-finger pinch on touch, double-click,
 *   + / − keys; drag to pan once zoomed. Borders stay hairline and bubbles keep their size.
 * - The land rises in from west to east the first time the map scrolls into view, bubbles grow
 *   after it; new data cross-fades (on the compositor). All instant with reduced motion.
 * - The outlines (Natural Earth 1:110m, public domain) load on demand in their own chunk.
 *
 * Keyboard: Tab focuses the map; the arrow keys move to the neighbouring country, Page Up and Page Down step through countries by value, Home and End jump to the highest and lowest, typing a name jumps to it, + and - zoom and 0 resets, Escape clears. With `onSelect`, Enter selects the country being read. The zoom buttons are tab stops.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; keyboard moves announce the country and its value, and the legend names the colour scale. The choropleth has no `patterns` prop on purpose: it is one ordered ramp that differs in lightness, not a set of unordered categories, so it stays readable in greyscale and with colour blindness, countries without data are already hatched, and every value is in the tooltip, the keyboard readout and the table. `WorldMapTable` is the table view (a ranked list).
 * Glass and motion: the tooltip is the shared glass surface; the map itself has no backdrop blur. Reduced motion draws, zooms and cross-fades instantly.
 *
 * @example
 * ```tsx
 * import { WorldMap } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <WorldMap
 *       data={[
 *         { id: "USA", value: 4200 },
 *         { id: "DEU", value: 1800 },
 *         { id: "IND", value: 2600 },
 *       ]}
 *       valueLabel="Users"
 *       aria-label="Users by country"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/world-map
 */
export function WorldMap({
  data: dataProp = NO_DATA,
  points: pointsProp,
  mode = "choropleth",
  scale = "sequential",
  midpoint = 0,
  scaleType = "linear",
  color = 1,
  divergingColors = [2, 7],
  domain,
  steps = 0,
  format: formatProp,
  locale = "en",
  valueLabel,
  legend = true,
  zoomable = true,
  maxZoom = 8,
  shapes: shapesProp,
  onSelect,
  emptyState,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<WorldMapProps>) {
  const labels = { ...defaultWorldMapLabels, ...labelOverrides };
  // New data re-colours the map in a low-priority render, after everything else the same update
  // changes (a headline number, a switch): the input that caused it never waits for the map.
  const platform = useShortcutPlatform();
  const data = useDeferredValue(dataProp);
  const points = useDeferredValue(pointsProp);
  const format = formatProp ?? defaultCompact(locale);
  const reduced = useSheenReducedMotion();
  const uid = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const mapRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const zoomRef = useRef<SVGGElement>(null);
  const zoom1Ref = useRef<SVGGElement>(null);
  const zoom2Ref = useRef<SVGGElement>(null);
  const layerRef = useRef<SVGGElement>(null);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const { shapes, failed } = useWorldShapes(shapesProp);
  const ready = !!shapes && width > 0;
  const play = useEntrance(rootRef, reduced) && ready;
  const docked = useDockedReadout(width);
  const { fromKeyboard, fromPointer, announce } = useInputSource();

  const mapH = width > 0 ? Math.round((width * WORLD_FRAME_HEIGHT) / WORLD_FRAME_WIDTH) : 0;
  const dock = docked ? DOCK_BAND : 0;
  const unit = width > 0 ? WORLD_FRAME_WIDTH / width : 1; // frame units per screen px

  /* ---------- Data ---------- */

  const { byShape, hasData, lo, hi, sorted, logLo, positionOf, fillOf, maxR, maxValue, items, ranked, rankOf } =
    useWorldMapData({
      shapes,
      data,
      points,
      mode,
      scale,
      scaleType,
      midpoint,
      color,
      divergingColors,
      domain,
      steps,
      locale,
      width,
    });

  /* ---------- View (zoom / pan) ---------- */

  const mapView = useWorldMapView({ unit, ready, mode, maxZoom, reduced, zoomRef, zoom1Ref, zoom2Ref });
  const { view, moving, hatchRef, bubblesRef, pointer, setPointer, zoomAt, resetView } = mapView;

  /* ---------- Active item ---------- */

  const [active, setActive] = useState<number | null>(null);
  const act = active !== null && active < items.length ? active : null;
  const activeItem = act === null ? null : (items[act] ?? null);

  const select = (i: number) => {
    const it = items[i];
    if (!it || !onSelect) return;
    onSelect({ id: it.key, name: it.name, value: it.value, kind: it.shape === null ? "point" : "country" });
  };

  /* ---------- Pointer and keyboard ---------- */

  const { gesture, lastPointerType, toFrame, onPointerDown, onPointerMove, endGesture, wheelHint } = useWorldMapPointer(
    {
      svgRef,
      mapRef,
      view: mapView,
      items,
      mode,
      unit,
      zoomable,
      maxZoom,
      ready,
      fromPointer,
      setActive,
      select,
    },
  );
  const { onKeyDown, zoomButton } = useWorldMapKeyboard({
    view: mapView,
    items,
    ranked,
    act,
    activeItem,
    zoomable,
    locale,
    fromKeyboard,
    setActive,
    select,
    onSelect,
  });

  /* ---------- Layers ---------- */

  // The colour of every country, and a key that changes when any of them does.
  const fills = useMemo(
    () => (shapes ? shapes.map((_, i) => (mode === "bubble" ? LAND : fillOf(byShape.get(i)?.value ?? null))) : null),
    [shapes, byShape, fillOf, mode],
  );
  const version = useMemo(() => (fills ? hash(fills.map((f) => f ?? "-").join(",")) : ""), [fills]);

  // Two country layers stay mounted. New colours go into the hidden one, which then becomes the
  // front: it fades in over the old (when it's on top), or the old one fades out above it. So a
  // data change creates no outlines, and switching back to the previous data writes nothing at all.
  type Slot = { version: string; fills: readonly (string | null)[] } | null;
  const [layers, setLayers] = useState<{ slots: [Slot, Slot]; front: 0 | 1 }>({ slots: [null, null], front: 0 });
  if (fills && layers.slots[layers.front]?.version !== version) {
    const back = layers.front === 0 ? 1 : 0;
    if (!layers.slots[0]) setLayers({ slots: [{ version, fills }, null], front: 0 });
    else if (layers.slots[back]?.version === version) setLayers({ slots: layers.slots, front: back });
    else
      setLayers({
        slots: back === 0 ? [{ version, fills }, layers.slots[1]] : [layers.slots[0], { version, fills }],
        front: back,
      });
  }
  const front = layers.front;

  // The hidden layer is drawn in small chunks while the page is idle, after the entrance: by the
  // first data change its outlines already exist. (A change before that draws the rest at once.)
  const total = shapes?.length ?? 0;
  const [backCount, setBackCount] = useState(0);
  const needBack = !!layers.slots[1];
  useEffect(() => {
    if (!play || !total || backCount >= total || needBack) return;
    const idle = typeof requestIdleCallback === "function";
    const step = () => setBackCount((n) => Math.min(total, n + 30));
    const id = idle
      ? requestIdleCallback(step, { timeout: 2000 })
      : window.setTimeout(step, backCount === 0 ? 1500 : 50);
    return () => (idle ? cancelIdleCallback(id) : window.clearTimeout(id));
  }, [play, total, backCount, needBack]);
  const layerCount = (i: 0 | 1) => (i === 0 || needBack ? total : backCount);

  // The cross-fade: one opacity animation on the <svg> that holds layer 1 (on top), so it runs on
  // the compositor. It holds its end value until the layer it faded out is hidden (same commit),
  // then lets go, so the layer never flashes back nor stays a compositor layer for nothing.
  const topLayerRef = useRef<SVGSVGElement>(null);
  const [fading, setFading] = useState(false);
  const shownFront = useRef<0 | 1>(0);
  const fadeAnim = useRef<Animation | null>(null);
  useLayoutEffect(() => {
    if (fading) return;
    fadeAnim.current?.cancel();
    fadeAnim.current = null;
  }, [fading]);
  useLayoutEffect(() => {
    if (shownFront.current === front) return;
    shownFront.current = front;
    const top = topLayerRef.current;
    if (reduced || !top || typeof top.animate !== "function") return;
    // Front on top: it fades in over the old. Front underneath: the old one, on top, fades out.
    const anim = top.animate(front === 1 ? [{ opacity: 0 }, { opacity: 1 }] : [{ opacity: 1 }, { opacity: 0 }], {
      duration: duration.slow * 1000,
      easing: cssEase(ease.out),
      fill: "forwards",
    });
    fadeAnim.current = anim;
    setFading(true);
    anim.finished.then(
      () => setFading(false),
      () => undefined, // replaced by the next cross-fade
    );
    return () => {
      anim.cancel();
      setFading(false);
    };
  }, [front, reduced]);

  useBandsEntrance(layerRef, play, reduced);

  /* ---------- Render ---------- */

  const glow = `drop-shadow(0 0 6px light-dark(transparent, color-mix(in oklab, ${slotColor(color)} 70%, transparent))) drop-shadow(0 1px 2px light-dark(var(--sheen-shadow-far), transparent))`;
  const k = view.k;

  let tooltip: ReactNode = null;
  let announcement = "";
  if (activeItem && act !== null && !moving && width > 0) {
    const value = activeItem.value === null ? labels.noData : format(activeItem.value);
    const rank = rankOf.get(act);
    const rankText = rank !== undefined && ranked.length > 1 ? labels.rank(rank, ranked.length) : "";
    const measure = activeItem.value === null ? "" : (valueLabel ?? "");
    const fill =
      activeItem.value === null
        ? null
        : activeItem.shape !== null && mode !== "bubble"
          ? fillOf(activeItem.value)
          : slotColor(color);
    announcement = `${activeItem.name}: ${value}${rankText ? `, ${rankText}` : ""}`;
    if (docked) {
      tooltip = (
        <DockedReadout
          title={activeItem.name}
          value={value}
          color={fill}
          details={[measure, rankText].filter(Boolean)}
        />
      );
    } else {
      const rows = [
        { label: isolate(measure), value: isolate(value), color: fill ?? "transparent", kind: "rect" as const },
      ];
      if (rankText) rows.push({ label: isolate(rankText), value: "", color: "transparent", kind: "rect" });
      let anchor: { x: number; y: number; w: number; h: number };
      if (pointer) anchor = { x: pointer.x - 1, y: pointer.y - 1, w: 2, h: 2 };
      else {
        const s = width / WORLD_FRAME_WIDTH;
        const cx = (activeItem.x * k + view.x) * s;
        const cy = (activeItem.y * k + view.y) * s;
        const half = Math.max(6, activeItem.r);
        anchor = { x: cx - half, y: cy - half, w: half * 2, h: half * 2 };
      }
      tooltip = (
        <ChartTip title={isolate(activeItem.name)} rows={rows} anchor={anchor} bounds={{ w: width, h: mapH }} />
      );
    }
  }

  // On narrow maps the zoom buttons (44px on touch) would cover the map: they move under it, in a row.
  const compact = width > 0 && width < 480;

  const legendEl = (() => {
    if (!legend || !hasData) return null;
    if (mode === "bubble")
      return (
        <LegendRow caption={valueLabel}>
          <BubbleLegend max={maxValue} maxR={maxR} color={color} format={format} />
        </LegendRow>
      );
    const v = activeItem?.value ?? null;
    if (scale === "diverging")
      return (
        <LegendRow caption={valueLabel}>
          <DivergingLegend
            lo={lo}
            mid={midpoint}
            hi={hi}
            colors={divergingColors}
            format={format}
            width={compact ? 120 : 160}
            marker={v === null ? null : divergingPosition(v, lo, midpoint, hi, steps)}
          />
        </LegendRow>
      );
    return (
      <LegendRow caption={scaleType === "log" && valueLabel ? labels.logScale(valueLabel) : valueLabel}>
        <SequentialLegend
          className="flex-nowrap"
          min={scaleType === "log" ? logLo : scaleType === "quantile" ? (sorted[0] ?? lo) : lo}
          max={scaleType === "quantile" ? (sorted[sorted.length - 1] ?? hi) : hi}
          color={color}
          steps={steps}
          floor={MAP_RAMP_FLOOR}
          format={format}
          marker={v === null ? null : positionOf(v)}
        />
      </LegendRow>
    );
  })();
  const ctrlBtn =
    "relative grid size-8 place-items-center text-sheen-fg transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover " +
    "disabled:cursor-default disabled:text-sheen-fg-subtle disabled:hover:bg-transparent any-pointer-coarse:size-11 " +
    "focus-visible:z-1 focus-visible:outline-solid focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus " +
    "motion-ok:active:scale-95 motion-ok:transition-[background-color,transform]";

  const sep = <span aria-hidden className={compact ? "my-1.5 w-px bg-sheen-border" : "mx-1.5 h-px bg-sheen-border"} />;
  const zoomControls = (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- focus-tracking handlers (onBlur/onFocus) on the zoom button group clear the readout when focus leaves; the group itself is not a widget
    <div
      className={cn(
        // A solid surface with the glass rim and shadow, but no backdrop filter: a page of maps
        // must not spend the glass budget on their zoom buttons.
        "flex overflow-hidden rounded-sheen-md border border-(--sheen-glass-border) text-sheen-fg",
        "bg-[color-mix(in_oklab,var(--sheen-chart-surface)_94%,transparent)] [background-image:var(--sheen-glass-specular)] shadow-(--sheen-glass-1-shadow)",
        compact ? "flex-row" : "absolute end-2 flex-col",
      )}
      style={compact ? undefined : { top: dock + 8 }}
      role="group"
      aria-label={labels.zoomControls(ariaLabel)}
      onBlur={(e) => {
        if (!rootRef.current?.contains(e.relatedTarget)) {
          setActive(null);
          setPointer(null);
        }
      }}
    >
      <button
        type="button"
        aria-label={labels.zoomIn}
        className={ctrlBtn}
        disabled={k >= maxZoom - 1e-6}
        onClick={() => zoomButton(2)}
      >
        <svg
          aria-hidden
          width={14}
          height={14}
          viewBox="0 0 14 14"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.6}
          strokeLinecap="round"
        >
          <path d="M7 2.5v9M2.5 7h9" />
        </svg>
      </button>
      {sep}
      <button
        type="button"
        aria-label={labels.zoomOut}
        className={ctrlBtn}
        disabled={k <= 1 + 1e-6}
        onClick={() => zoomButton(0.5)}
      >
        <svg
          aria-hidden
          width={14}
          height={14}
          viewBox="0 0 14 14"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.6}
          strokeLinecap="round"
        >
          <path d="M2.5 7h9" />
        </svg>
      </button>
      {sep}
      <button
        type="button"
        aria-label={labels.resetZoom}
        className={ctrlBtn}
        disabled={k <= 1 + 1e-6}
        onClick={resetView}
      >
        <svg
          aria-hidden
          width={14}
          height={14}
          viewBox="0 0 14 14"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.5}
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M2 5V2h3M12 9v3H9M2 9v3h3M12 5V2H9" />
        </svg>
      </button>
    </div>
  );
  const showNoDataKey = legend && mode !== "bubble" && hasData && byShape.size < (shapes?.length ?? 0);

  return (
    <div
      data-slot="world-map"
      {...rest}
      ref={rootMerged}
      className={cn("relative flex w-full min-w-0 flex-col gap-3", className)}
      style={{ "--geo-glow": glow } as CSSProperties}
    >
      <div ref={measureRef} className="relative w-full" style={{ paddingTop: dock }}>
        {width > 0 && (
          <>
            <ChartFigure
              as="div"
              ref={mapRef}
              roleDescription={labels.roleDescription}
              label={ariaLabel}
              description={
                mode === "bubble"
                  ? resolveInstructions(labels.instructionsBubble)
                  : resolveInstructions(labels.instructions)
              }
              tabIndex={0}
              onKeyDown={onKeyDown}
              onBlur={(e) => {
                // Focus moving to the zoom buttons keeps the place being read (they zoom around it).
                if (!rootRef.current?.contains(e.relatedTarget)) {
                  setActive(null);
                  setPointer(null);
                }
              }}
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={endGesture}
              onPointerCancel={endGesture}
              onPointerLeave={(e) => {
                if (e.pointerType === "mouse" && !gesture.current) {
                  setActive(null);
                  setPointer(null);
                }
              }}
              onDoubleClick={(e) => {
                // A touch double tap already zoomed in endGesture: skip the dblclick the browser adds.
                if (!zoomable || lastPointerType.current === "touch") return;
                const p = toFrame(e.clientX, e.clientY);
                if (p) zoomAt(e.shiftKey ? 0.5 : 2, p.vx, p.vy);
              }}
              className={cn(
                "relative overflow-hidden rounded-sheen-md select-none",
                chartFocusClass,
                k > 1
                  ? "cursor-grab active:cursor-grabbing"
                  : onSelect && mode !== "bubble"
                    ? "cursor-pointer"
                    : undefined,
              )}
              style={{ height: mapH, touchAction: k > 1 ? "none" : "pan-y" }}
            >
              {/* Three stacked SVGs share one frame and one view transform:
                  1. the sea, graticule and country layer 0;
                  2. country layer 1, whose cross-fade is an opacity animation on the <svg> itself,
                     so it runs on the compositor (no repaint per frame);
                  3. marks: the active country's outline and the bubbles. */}
              <svg
                ref={svgRef}
                aria-hidden
                width={width}
                height={mapH}
                viewBox={`0 0 ${WORLD_FRAME_WIDTH} ${WORLD_FRAME_HEIGHT}`}
                className="block"
              >
                <defs>
                  <HatchPattern ref={hatchRef} id={`${uid}-nodata`} scale={unit * 0.8} />
                  <linearGradient id={`${uid}-sea`} x1="0" x2="0" y1="0" y2="1">
                    <stop offset="0" style={{ stopColor: `color-mix(in oklab, ${slotColor(7)} 9%, transparent)` }} />
                    <stop offset="1" style={{ stopColor: `color-mix(in oklab, ${slotColor(1)} 5%, transparent)` }} />
                  </linearGradient>
                </defs>
                <g ref={zoomRef}>
                  <path
                    d={SPHERE_PATH}
                    fill={`url(#${uid}-sea)`}
                    stroke="var(--sheen-chart-grid)"
                    strokeWidth={1}
                    vectorEffect="non-scaling-stroke"
                  />
                  <path
                    d={GRATICULE_PATH}
                    fill="none"
                    stroke="var(--sheen-chart-grid)"
                    strokeWidth={1}
                    vectorEffect="non-scaling-stroke"
                  />
                  <g
                    ref={layerRef}
                    opacity={play ? 1 : 0}
                    visibility={front === 0 || fading ? undefined : "hidden"}
                    className="forced-color-adjust-none"
                  >
                    {shapes && (
                      <CountryLayer
                        shapes={shapes}
                        fills={layers.slots[0]?.fills ?? null}
                        count={layerCount(0)}
                        hatch={`url(#${uid}-nodata)`}
                        hittable={mode !== "bubble"}
                        entrance
                      />
                    )}
                  </g>
                </g>
              </svg>
              <svg
                ref={topLayerRef}
                aria-hidden
                width={width}
                height={mapH}
                viewBox={`0 0 ${WORLD_FRAME_WIDTH} ${WORLD_FRAME_HEIGHT}`}
                visibility={front === 1 || fading ? undefined : "hidden"}
                // Hit-testable only while it is the front layer (the one under it is hidden then).
                className={cn("absolute inset-0 block", front === 1 && !fading ? undefined : "pointer-events-none")}
              >
                <g ref={zoom1Ref} className="forced-color-adjust-none">
                  {shapes && (
                    <CountryLayer
                      shapes={shapes}
                      fills={layers.slots[1]?.fills ?? null}
                      count={layerCount(1)}
                      hatch={`url(#${uid}-nodata)`}
                      hittable={mode !== "bubble"}
                      entrance={false}
                    />
                  )}
                </g>
              </svg>
              <svg
                aria-hidden
                width={width}
                height={mapH}
                viewBox={`0 0 ${WORLD_FRAME_WIDTH} ${WORLD_FRAME_HEIGHT}`}
                className="pointer-events-none absolute inset-0 block"
              >
                <g ref={zoom2Ref}>
                  {/* The active country: a crisp ring that lifts it (a glow in dark mode), never dimming the rest. */}
                  {activeItem && activeItem.shape !== null && mode !== "bubble" && shapes?.[activeItem.shape] && (
                    <path
                      d={itemAt(shapes, activeItem.shape).d}
                      vectorEffect="non-scaling-stroke"
                      strokeWidth={1.75}
                      strokeLinejoin="round"
                      style={{ fill: fillOf(activeItem.value) ?? `url(#${uid}-nodata)`, filter: glow }}
                      className="stroke-sheen-fg forced-colors:stroke-[Highlight]"
                    />
                  )}

                  {mode === "bubble" && (
                    <g ref={bubblesRef} visibility={play ? undefined : "hidden"} className="forced-color-adjust-none">
                      {items.map((it, i) => (
                        <Bubble
                          key={it.key}
                          cx={it.x}
                          cy={it.y}
                          r={it.r}
                          unit={unit}
                          color={color}
                          active={i === act}
                          delay={0.35 + Math.min(0.6, i * 0.035)}
                          play={play}
                          reduced={reduced}
                        />
                      ))}
                    </g>
                  )}
                </g>
              </svg>

              {/* Not ready yet, failed, or nothing to show. */}
              {(!shapes || !hasData) && (
                <div className="pointer-events-none absolute inset-0 grid place-items-center">
                  {failed ? (
                    <p className="glass-3 rounded-sheen-md px-3 py-1.5 text-sm text-sheen-fg-muted">
                      {labels.loadError}
                    </p>
                  ) : shapes && !hasData ? (
                    <p className="glass-3 rounded-sheen-md px-3 py-1.5 text-sm text-sheen-fg-muted">
                      {emptyState ?? labels.noData}
                    </p>
                  ) : null}
                </div>
              )}

              {/* Mounted only while it shows, so an invisible pill never holds a backdrop filter. */}
              <AnimatePresence>
                {zoomable && wheelHint && (
                  <motion.p
                    aria-hidden
                    initial={{ opacity: 0, y: reduced ? 0 : 4 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, transition: { duration: reduced ? 0 : duration.exit, ease: ease.exit } }}
                    transition={{ duration: reduced ? 0 : duration.base, ease: ease.out }}
                    className="glass-3 pointer-events-none absolute inset-x-0 bottom-3 mx-auto w-fit rounded-sheen-full px-3 py-1.5 text-xs text-sheen-fg"
                  >
                    {labels.zoomHint(platform === "mac")}
                  </motion.p>
                )}
              </AnimatePresence>
            </ChartFigure>

            {zoomable && shapes && !compact && zoomControls}

            {tooltip ??
              (docked && hasData && (
                <ChartDockHint>{mode === "bubble" ? labels.hintBubble : labels.hint}</ChartDockHint>
              ))}
          </>
        )}
        {width === 0 && <div aria-hidden style={{ aspectRatio: `${WORLD_FRAME_WIDTH} / ${WORLD_FRAME_HEIGHT}` }} />}
      </div>

      {(!!legendEl || showNoDataKey || (compact && zoomable && shapes)) && (
        // Maps never mirror, so neither do their scales: low → high reads left to right on every page.
        <div dir="ltr" className="flex min-h-10 flex-wrap items-center justify-end gap-x-5 gap-y-2">
          {compact && zoomable && shapes && <div className="me-auto">{zoomControls}</div>}
          {legendEl}
          {showNoDataKey && <NoDataKey label={labels.noDataKey} />}
        </div>
      )}
      <ChartAnnouncer text={announce(announcement)} />
    </div>
  );
}

"use client";

import { useCallback, useMemo } from "react";

import { clamp, type ChartColor } from "../chart-utils";
import { scalePosition, sequentialColor } from "../heatmap";
import type { WorldCountryShape } from "../geo/world-110m";
import { codeIndex, normalizeCode, projectWorld, worldCountryName } from "./projection";
import { divergingColor, divergingPosition } from "./parts";
import type { WorldMapDatum, WorldMapPoint, WorldMapProps } from "./types";

/** Lightest step of a map's colour ramp: raised from the heatmap's 0.08 so data out-contrasts the faint no-data land. */
export const MAP_RAMP_FLOOR = 0.3;

/** One thing the keyboard, pointer and tooltip move between: a country or a bubble. @internal */
export type MapItem = {
  /** Index into shapes (countries) or into the bubble list. */
  key: string;
  name: string;
  value: number | null;
  x: number;
  y: number;
  /** Bubble radius in px (bubble mode). */
  r: number;
  shape: number | null;
};

/** What the map's data derivation reads. @internal */
export type WorldMapDataInput = {
  shapes: readonly WorldCountryShape[] | null | undefined;
  data: readonly WorldMapDatum[];
  points: readonly WorldMapPoint[] | undefined;
  mode: NonNullable<WorldMapProps["mode"]>;
  scale: NonNullable<WorldMapProps["scale"]>;
  scaleType: NonNullable<WorldMapProps["scaleType"]>;
  midpoint: number;
  color: ChartColor;
  divergingColors: [ChartColor, ChartColor];
  domain: [number, number] | undefined;
  steps: number;
  locale: string;
  width: number;
};

/**
 * Everything the map derives from its props: values by country, the colour scale (`fillOf`), bubble
 * sizes, and the ordered `items` (with their rank) that the keyboard, pointer and tooltip move between.
 * @internal
 */
export function useWorldMapData(o: WorldMapDataInput) {
  const { shapes, data, points, mode, scale, scaleType, midpoint, color, divergingColors, domain, steps, locale } = o;
  const { width } = o;
  const index = useMemo(() => (shapes ? codeIndex(shapes) : new Map<string, number>()), [shapes]);
  const names = useMemo(() => (shapes ? shapes.map((s) => worldCountryName(s, locale)) : []), [shapes, locale]);
  /** Value and label per shape index. */
  const byShape = useMemo(() => {
    const map = new Map<number, { value: number | null; label?: string }>();
    for (const d of data) {
      const i = index.get(normalizeCode(d.id));
      if (i === undefined) continue;
      const v = typeof d.value === "number" && Number.isFinite(d.value) ? d.value : null;
      map.set(i, { value: v, label: d.label });
    }
    return map;
  }, [data, index]);

  const values = useMemo(() => {
    const list: number[] = [];
    if (mode === "bubble" && points) {
      for (const p of points) if (Number.isFinite(p.value)) list.push(p.value);
    } else {
      for (const { value } of byShape.values()) if (value !== null) list.push(value);
    }
    return list;
  }, [byShape, points, mode]);
  const hasData = values.length > 0;

  const [lo, hi] = useMemo<[number, number]>(() => {
    if (domain) return domain;
    if (!values.length) return [0, 0];
    let a = Infinity;
    let b = -Infinity;
    for (const v of values) {
      a = Math.min(a, v);
      b = Math.max(b, v);
    }
    if (scale === "diverging") {
      const reach = Math.max(Math.abs(a - midpoint), Math.abs(b - midpoint)) || 1;
      return [midpoint - reach, midpoint + reach];
    }
    return [Math.min(0, a), b];
  }, [values, domain, scale, midpoint]);

  // Where a value sits on a sequential scale (0–1), for each scale type.
  const sorted = useMemo(() => [...values].sort((a, b) => a - b), [values]);
  const logLo = useMemo(() => {
    const floor = domain && domain[0] > 0 ? domain[0] : (sorted.find((v) => v > 0) ?? 1);
    return Math.max(1e-12, Math.min(floor, hi > 0 ? hi : floor));
  }, [sorted, domain, hi]);
  const positionOf = useCallback(
    (value: number) => {
      if (scaleType === "log" && hi > 0) {
        const a = Math.log10(logLo);
        const b = Math.log10(hi);
        return scalePosition(Math.log10(Math.max(logLo, value)), a, b, steps);
      }
      if (scaleType === "quantile" && sorted.length > 1) {
        // Share of values below this one (ties share the middle of their run).
        let below = 0;
        let equal = 0;
        for (const v of sorted) {
          if (v < value) below++;
          else if (v === value) equal++;
        }
        const t = (below + Math.max(0, equal - 1) / 2) / (sorted.length - 1);
        return steps >= 2 ? Math.min(steps - 1, Math.floor(t * steps)) / (steps - 1) : clamp(t, 0, 1);
      }
      return scalePosition(value, lo, hi, steps);
    },
    [scaleType, lo, hi, logLo, sorted, steps],
  );

  // The two hues as plain values, so a new (but equal) array prop never re-colours the map.
  const [divLow, divHigh] = divergingColors;
  const fillOf = useCallback(
    (value: number | null) => {
      if (value === null) return null;
      if (scale === "diverging")
        return divergingColor(divergingPosition(value, lo, midpoint, hi, steps), [divLow, divHigh]);
      return sequentialColor(positionOf(value), color, MAP_RAMP_FLOOR);
    },
    [scale, lo, hi, midpoint, steps, color, divLow, divHigh, positionOf],
  );

  // Bubble sizes: area ∝ value; the largest bubble scales with the map (10–30px).
  const maxR = clamp(width * 0.032, 10, 30);
  const maxValue = values.reduce((m, v) => Math.max(m, v), 0);
  const radius = useCallback(
    (v: number) => (v > 0 && maxValue > 0 ? Math.max(4, Math.sqrt(v / maxValue) * maxR) : 0),
    [maxValue, maxR],
  );

  /** What the keyboard, pointer and tooltip move between. */
  const items = useMemo<MapItem[]>(() => {
    if (!shapes) return [];
    if (mode === "bubble") {
      const list: MapItem[] = [];
      if (points) {
        points.forEach((p) => {
          if (!Number.isFinite(p.value) || p.value <= 0) return;
          const [x, y] = projectWorld(p.lon, p.lat);
          list.push({ key: p.id ?? p.label, name: p.label, value: p.value, x, y, r: radius(p.value), shape: null });
        });
      } else {
        for (const [i, d] of byShape) {
          const s = shapes[i];
          if (!s || d.value === null || d.value <= 0) continue;
          list.push({
            key: s.id,
            name: d.label ?? names[i] ?? s.name,
            value: d.value,
            x: s.c[0],
            y: s.c[1],
            r: radius(d.value),
            shape: i,
          });
        }
      }
      // Largest first, so small bubbles draw on top.
      return list.sort((a, b) => (b.value ?? 0) - (a.value ?? 0));
    }
    return shapes.map((s, i) => {
      const d = byShape.get(i);
      return {
        key: s.id,
        name: d?.label ?? names[i] ?? s.name,
        value: d?.value ?? null,
        x: s.c[0],
        y: s.c[1],
        r: 0,
        shape: i,
      };
    });
  }, [shapes, mode, points, byShape, names, radius]);

  /** Items with a value, highest first (rank order). */
  const ranked = useMemo(
    () =>
      items
        .map((it, i) => ({ i, v: it.value }))
        .filter((e): e is { i: number; v: number } => e.v !== null)
        .sort((a, b) => b.v - a.v)
        .map((e) => e.i),
    [items],
  );
  const rankOf = useMemo(() => new Map(ranked.map((i, r) => [i, r + 1])), [ranked]);
  return { byShape, hasData, lo, hi, sorted, logLo, positionOf, fillOf, maxR, maxValue, items, ranked, rankOf };
}

"use client";

import {
  useEffect,
  useEffectEvent,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type RefObject,
} from "react";

import { clamp, itemAt } from "../chart-utils";
import { WORLD_FRAME_HEIGHT, WORLD_FRAME_WIDTH } from "./projection";
import type { MapItem as Item } from "./data";
import type { useWorldMapView, MapView as View } from "./view";

type MapViewState = ReturnType<typeof useWorldMapView>;

/** What the map's pointer handling reads and changes. @internal */
export type WorldMapPointerInput = {
  svgRef: RefObject<SVGSVGElement | null>;
  mapRef: RefObject<HTMLDivElement | null>;
  view: MapViewState;
  items: Item[];
  mode: string;
  unit: number;
  zoomable: boolean;
  maxZoom: number;
  ready: boolean;
  fromPointer: () => void;
  setActive: (i: number | null) => void;
  select: (i: number) => void;
};

/**
 * The map's pointer handling: hover, tap-to-pin, drag to pan, two-finger pinch, double tap to zoom, and
 * the native wheel listener (⌘/Ctrl + wheel and trackpad pinch zoom; a plain wheel scrolls the page and
 * flashes a hint).
 * @internal
 */
export function useWorldMapPointer(o: WorldMapPointerInput) {
  const { svgRef, mapRef, items, mode, unit, zoomable, maxZoom, ready, fromPointer, setActive, select } = o;
  const { zk, zx, zy, setViewState, setMoving, clampView, setPointer, zoomAt } = o.view;
  const { target: targetRef, viewAnim: viewAnimRef } = o.view;
  const pointers = useRef(new Map<number, { x: number; y: number }>());
  const gesture = useRef<{
    startX: number;
    startY: number;
    moved: boolean;
    view: View;
    dist: number;
    mid: [number, number];
  } | null>(null);
  const lastTap = useRef<{ t: number; x: number; y: number } | null>(null);
  /** Touch double taps are handled in endGesture: the browser's own dblclick that follows is ignored. */
  const lastPointerType = useRef("mouse");

  /** Client point → viewBox point (before the zoom transform) and frame point (after it). */
  const toFrame = (clientX: number, clientY: number) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return null;
    const vx = ((clientX - rect.left) / rect.width) * WORLD_FRAME_WIDTH;
    const vy = ((clientY - rect.top) / rect.height) * WORLD_FRAME_HEIGHT;
    const k = zk.get();
    return {
      vx,
      vy,
      fx: (vx - zx.get()) / k,
      fy: (vy - zy.get()) / k,
      px: clientX - rect.left,
      py: clientY - rect.top,
    };
  };

  /** The item under a pointer event: the country path it hit, or the bubble it's on / nearest to it. */
  const hitTest = (clientX: number, clientY: number): number | null => {
    if (mode === "bubble") {
      const p = toFrame(clientX, clientY);
      if (!p) return null;
      const k = zk.get();
      let best: number | null = null;
      let bestScore = Infinity;
      for (let i = 0; i < items.length; i++) {
        const it = itemAt(items, i);
        const d = Math.hypot(it.x - p.fx, it.y - p.fy) / (unit / k); // in screen px
        // Inside a bubble beats near one; among those, the smallest wins (it's drawn on top).
        const score = d <= it.r ? it.r - 1000 : d;
        if (d <= Math.max(it.r, 12) && score < bestScore) {
          bestScore = score;
          best = i;
        }
      }
      return best;
    }
    // Hit-test the real outlines (pointer capture retargets events, so not event.target).
    const hit = document.elementFromPoint(clientX, clientY)?.closest("[data-shape]");
    if (!hit || !mapRef.current?.contains(hit)) return null;
    const i = Number(hit.getAttribute("data-shape"));
    return Number.isInteger(i) ? i : null;
  };

  function onPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    lastPointerType.current = event.pointerType;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    pointers.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    const view0 = { k: zk.get(), x: zx.get(), y: zy.get() };
    if (pointers.current.size === 2 && zoomable) {
      // Fingers take over from any zoom still gliding.
      viewAnimRef.current.forEach((a) => a.stop());
      viewAnimRef.current = [];
      const [a, b] = [...pointers.current.values()];
      if (a && b) {
        const p = toFrame((a.x + b.x) / 2, (a.y + b.y) / 2);
        gesture.current = {
          startX: 0,
          startY: 0,
          moved: true,
          view: view0,
          dist: Math.hypot(a.x - b.x, a.y - b.y),
          mid: [p?.vx ?? 0, p?.vy ?? 0],
        };
        setPointer(null);
        setActive(null);
      }
    } else if (pointers.current.size === 1) {
      gesture.current = {
        startX: event.clientX,
        startY: event.clientY,
        moved: false,
        view: view0,
        dist: 0,
        mid: [0, 0],
      };
      // Capture only when a drag can pan; otherwise the browser keeps its own scrolling.
      if (view0.k > 1 && zoomable)
        if (typeof event.currentTarget.setPointerCapture === "function")
          event.currentTarget.setPointerCapture(event.pointerId);
    }
  }

  function onPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const g = gesture.current;
    if (pointers.current.has(event.pointerId))
      pointers.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    const rect = svgRef.current?.getBoundingClientRect();
    const toView = rect && rect.width > 0 ? WORLD_FRAME_WIDTH / rect.width : unit;

    // Pinch: zoom by the change in finger distance, around the starting midpoint, and pan with it.
    if (g && pointers.current.size === 2 && zoomable) {
      const [a, b] = [...pointers.current.values()];
      if (!a || !b || g.dist === 0) return;
      const factor = Math.hypot(a.x - b.x, a.y - b.y) / g.dist;
      const mid = toFrame((a.x + b.x) / 2, (a.y + b.y) / 2);
      if (!mid) return;
      const nk = clamp(g.view.k * factor, 1, maxZoom);
      const px = (g.mid[0] - g.view.x) / g.view.k;
      const py = (g.mid[1] - g.view.y) / g.view.k;
      const v = clampView({ k: nk, x: mid.vx - px * nk, y: mid.vy - py * nk });
      zk.set(v.k);
      zx.set(v.x);
      zy.set(v.y);
      return;
    }

    // Drag to pan (only when zoomed in).
    if (g && pointers.current.size === 1 && (event.buttons & 1 || event.pointerType === "touch")) {
      const dx = event.clientX - g.startX;
      const dy = event.clientY - g.startY;
      if (!g.moved && Math.hypot(dx, dy) > 4 && g.view.k > 1 && zoomable) {
        g.moved = true;
        // The drag takes over from any zoom still gliding, from where it is now.
        if (viewAnimRef.current.length) {
          viewAnimRef.current.forEach((a) => a.stop());
          viewAnimRef.current = [];
          g.view = { k: zk.get(), x: zx.get(), y: zy.get() };
          g.startX = event.clientX;
          g.startY = event.clientY;
        }
        setMoving(true);
        setPointer(null);
      }
      if (g.moved) {
        const v = clampView({ k: g.view.k, x: g.view.x + dx * toView, y: g.view.y + dy * toView });
        zx.set(v.x);
        zy.set(v.y);
        return;
      }
    }

    if (event.pointerType === "mouse" && !g?.moved) {
      const i = hitTest(event.clientX, event.clientY);
      fromPointer();
      setActive(i);
      const p = toFrame(event.clientX, event.clientY);
      setPointer(i === null || !p ? null : { x: p.px, y: p.py });
    }
  }

  function endGesture(event: ReactPointerEvent<HTMLDivElement>) {
    const g = gesture.current;
    pointers.current.delete(event.pointerId);
    if (pointers.current.size > 0) {
      // One finger left after a pinch: carry on as a pan from here.
      const rest = [...pointers.current.values()][0];
      if (rest)
        gesture.current = {
          startX: rest.x,
          startY: rest.y,
          moved: true,
          view: { k: zk.get(), x: zx.get(), y: zy.get() },
          dist: 0,
          mid: [0, 0],
        };
      return;
    }
    gesture.current = null;
    if (g?.moved) {
      const v = { k: zk.get(), x: zx.get(), y: zy.get() };
      targetRef.current = v;
      setViewState(v);
      setMoving(false);
      return;
    }
    if (event.type !== "pointerup") return;
    // A tap or click: pin the tooltip on what's under it (or clear it on the ocean).
    const i = hitTest(event.clientX, event.clientY);
    const p = toFrame(event.clientX, event.clientY);
    fromPointer();
    setActive(i);
    setPointer(i === null || !p ? null : { x: p.px, y: p.py });
    if (i !== null) select(i);
    // Double tap zooms in (touch), like double-click does with a mouse.
    if (event.pointerType === "touch" && zoomable && p) {
      const now = performance.now();
      const last = lastTap.current;
      if (last && now - last.t < 320 && Math.hypot(last.x - event.clientX, last.y - event.clientY) < 24) {
        zoomAt(2, p.vx, p.vy);
        lastTap.current = null;
      } else lastTap.current = { t: now, x: event.clientX, y: event.clientY };
    }
  }

  // ⌘/Ctrl + wheel (and trackpad pinch, which arrives as ctrl + wheel) zooms; a plain wheel scrolls
  // the page and flashes a hint. Native listener: React's wheel listener is passive.
  const [wheelHint, setWheelHint] = useState(false);
  const hintTimer = useRef(0);
  const onWheel = useEffectEvent((e: WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const p = toFrame(e.clientX, e.clientY);
      if (!p) return;
      const factor = Math.exp(-clamp(e.deltaY, -60, 60) * (e.deltaMode === 1 ? 0.05 : 0.0035));
      zoomAt(factor, p.vx, p.vy, false);
      setWheelHint(false);
      return;
    }
    if (Math.abs(e.deltaY) < 4) return;
    setWheelHint(true);
    window.clearTimeout(hintTimer.current);
    hintTimer.current = window.setTimeout(() => setWheelHint(false), 1400);
  });
  useEffect(() => {
    const el = mapRef.current;
    if (!el || !zoomable || !ready) return;
    const listener = (e: WheelEvent) => onWheel(e);
    el.addEventListener("wheel", listener, { passive: false });
    return () => {
      el.removeEventListener("wheel", listener);
      window.clearTimeout(hintTimer.current);
    };
  }, [zoomable, ready, mapRef]);
  return { gesture, lastPointerType, toFrame, onPointerDown, onPointerMove, endGesture, wheelHint };
}

/** What the map's keyboard handling reads and changes. @internal */
export type WorldMapKeyboardInput = {
  view: MapViewState;
  items: Item[];
  ranked: number[];
  act: number | null;
  activeItem: Item | null;
  zoomable: boolean;
  locale: string;
  fromKeyboard: () => void;
  setActive: (i: number | null) => void;
  select: (i: number) => void;
  onSelect: unknown;
};

/**
 * The map's keyboard handling: arrows move to the neighbouring place, Page Up / Down step by rank, Home /
 * End jump, typing a name jumps to it, + - 0 zoom, Enter selects, Escape clears. Also the zoom buttons'
 * handler, which zooms around the place being read.
 * @internal
 */
export function useWorldMapKeyboard(o: WorldMapKeyboardInput) {
  const { items, ranked, act, activeItem, zoomable, locale, fromKeyboard, setActive, select, onSelect } = o;
  const { zk, zx, zy, setPointer, zoomAt, resetView, revealPoint } = o.view;
  const typeahead = useRef({ text: "", at: 0 });

  function move(next: number | null) {
    fromKeyboard();
    setPointer(null);
    setActive(next);
    const it = next === null ? null : items[next];
    if (it) revealPoint(it.x, it.y);
  }

  function neighbour(from: number, dir: "left" | "right" | "up" | "down"): number | null {
    const o = items[from];
    if (!o) return null;
    let best: number | null = null;
    let bestScore = Infinity;
    const horizontal = dir === "left" || dir === "right";
    for (let i = 0; i < items.length; i++) {
      const it = itemAt(items, i);
      if (i === from) continue;
      const dx = it.x - o.x;
      const dy = it.y - o.y;
      const along = dir === "right" ? dx : dir === "left" ? -dx : dir === "down" ? dy : -dy;
      const across = horizontal ? Math.abs(dy) : Math.abs(dx);
      if (along <= 1) continue;
      // Nearest along the arrow, strongly preferring places within a 60° cone of it.
      const score = along + across * 2.2 + (across > along * 1.7 ? WORLD_FRAME_WIDTH : 0);
      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (!items.length) return;
    const first = ranked[0] ?? 0;
    const cur = act;
    const key = event.key;
    let handled = true;
    switch (key) {
      case "ArrowRight":
      case "ArrowLeft":
      case "ArrowUp":
      case "ArrowDown": {
        const dir = key === "ArrowRight" ? "right" : key === "ArrowLeft" ? "left" : key === "ArrowUp" ? "up" : "down";
        move(cur === null ? first : (neighbour(cur, dir) ?? cur));
        break;
      }
      case "PageDown":
      case "PageUp": {
        if (!ranked.length) break;
        const r = cur === null ? -1 : ranked.indexOf(cur);
        const next = key === "PageDown" ? (r < 0 ? 0 : Math.min(ranked.length - 1, r + 1)) : r <= 0 ? 0 : r - 1;
        move(ranked[next] ?? first);
        break;
      }
      case "Home":
        move(ranked[0] ?? 0);
        break;
      case "End":
        move(ranked[ranked.length - 1] ?? items.length - 1);
        break;
      case "Enter":
      case " ":
        if (cur === null || !onSelect) return;
        select(cur);
        break;
      case "+":
      case "=":
      case "-":
      case "_": {
        if (!zoomable) return;
        // Zoom around the active place, else the middle of the view.
        const at = activeItem ? viewPoint(activeItem) : undefined;
        zoomAt(key === "+" || key === "=" ? 2 : 0.5, at?.[0], at?.[1]);
        break;
      }
      case "0":
        if (!zoomable) return;
        resetView();
        break;
      case "Escape":
        if (cur === null) {
          if (zk.get() > 1) resetView();
          else handled = false;
        } else move(null);
        break;
      default:
        handled = false;
    }
    if (!handled && key.length === 1 && /\p{L}/u.test(key) && !event.ctrlKey && !event.metaKey && !event.altKey) {
      // Type-ahead: jump to the next place whose name starts with what was typed.
      const now = event.timeStamp; // the same clock as performance.now(), stamped when the key arrived
      const ta = typeahead.current;
      ta.text = now - ta.at < 800 ? ta.text + key.toLowerCase() : key.toLowerCase();
      ta.at = now;
      const startAt = cur === null ? 0 : ta.text.length === 1 ? cur + 1 : cur;
      for (let n = 0; n < items.length; n++) {
        const i = (startAt + n) % items.length;
        if (items[i]?.name.toLocaleLowerCase(locale).startsWith(ta.text)) {
          move(i);
          break;
        }
      }
      handled = true;
    }
    if (handled) event.preventDefault();
  }

  /** An item's position in viewBox units (after the zoom transform). */
  const viewPoint = (it: Item): [number, number] => [it.x * zk.get() + zx.get(), it.y * zk.get() + zy.get()];

  /** The zoom buttons zoom around the place being read (a tapped country stays put), else the middle. */
  const zoomButton = (factor: number) => {
    const at = activeItem ? viewPoint(activeItem) : undefined;
    zoomAt(factor, at?.[0], at?.[1]);
  };
  return { onKeyDown, zoomButton };
}

"use client";

import {
  useEffectEvent,
  useId,
  useMemo,
  useRef,
  type ReactNode,
  type Ref,
  type RefObject,
  useLayoutEffect,
} from "react";
import { motion } from "motion/react";
import { cn } from "../../lib/cn";
import { duration, ease } from "../../motion/tokens";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { LegendKey } from "../chart-parts";
import { clamp, slotColor, TOOLTIP_DOCK_SPACE, type ChartColor, itemAt } from "../chart-utils";
import { hueMix } from "../heatmap";
import type { WorldCountryShape } from "../geo/world-110m";
import { WORLD_FRAME_WIDTH, r1 } from "./projection";

/* ======================================================================
 * Colour scales
 * ====================================================================== */

/** Land without a value, and the bubble map's land. */
export const LAND = "color-mix(in oklab, var(--sheen-fg-subtle) 16%, var(--sheen-chart-surface))";
/** Land without data: fainter than `LAND`, so hatched areas recede and the data stands out. */
const NO_DATA = "color-mix(in oklab, var(--sheen-fg-subtle) 7%, var(--sheen-chart-surface))";
/** Neutral centre of a diverging scale. */
export const NEUTRAL = "color-mix(in oklab, var(--sheen-fg-subtle) 22%, var(--sheen-chart-surface))";

/** One step of a diverging scale: t in [-1, 1], 0 is the neutral midpoint. */
export function divergingColor(t: number, [low, high]: [ChartColor, ChartColor] = [2, 7]) {
  const s = clamp(Number.isFinite(t) ? t : 0, -1, 1);
  if (s === 0) return NEUTRAL;
  return hueMix(s < 0 ? low : high, Math.abs(s), NEUTRAL);
}

/** Maps a value to a step position from -1 to 1 around `mid`, so a diverging scale can pick a colour (pure). */
export function divergingPosition(value: number, lo: number, mid: number, hi: number, steps: number) {
  let t = value < mid ? -(mid - value) / Math.max(1e-12, mid - lo) : (value - mid) / Math.max(1e-12, hi - mid);
  t = clamp(t, -1, 1);
  if (steps >= 2) t = Math.sign(t) * (Math.ceil(Math.abs(t) * steps - 1e-9) / steps);
  return t;
}

/* ======================================================================
 * Small pieces
 * ====================================================================== */

/** The hatch that marks "no data" (never painted as 0). */
export function HatchPattern({ id, scale = 1, ref }: { id: string; scale?: number; ref?: Ref<SVGPatternElement> }) {
  return (
    <pattern
      ref={ref}
      id={id}
      width={6}
      height={6}
      patternUnits="userSpaceOnUse"
      patternTransform={`rotate(45) scale(${scale})`}
    >
      <rect width={6} height={6} style={{ fill: NO_DATA }} />
      <line
        x1={0}
        y1={0}
        x2={0}
        y2={6}
        stroke="color-mix(in oklab, var(--sheen-fg-subtle) 14%, transparent)"
        strokeWidth={1}
      />
    </pattern>
  );
}

/** The legend key for regions without data: a hatched swatch and its label. */
export function NoDataKey({ label }: { label: string }) {
  const id = useId();
  return (
    <span className="inline-flex items-center gap-1.5 text-2xs text-sheen-fg-muted">
      <svg aria-hidden width={12} height={10} viewBox="0 0 12 10" className="shrink-0 forced-color-adjust-none">
        <defs>
          <HatchPattern id={id} />
        </defs>
        <rect
          x={0.5}
          y={0.5}
          width={11}
          height={9}
          rx={2.5}
          fill={`url(#${id})`}
          className="forced-colors:stroke-[CanvasText]"
        />
      </svg>
      {label}
    </span>
  );
}

/**
 * A legend's caption and its key. The caption wraps onto its own line on narrow maps; the key
 * (low value, ramp, high value) always stays on one line, so a value is never orphaned.
 */
export function LegendRow({ caption, children }: { caption?: ReactNode; children: ReactNode }) {
  return (
    <div aria-hidden className="flex flex-wrap items-center justify-end gap-x-3 gap-y-1">
      {caption && <span className="text-2xs font-medium text-sheen-fg-muted">{caption}</span>}
      {children}
    </div>
  );
}

/** Key to a diverging scale: low hue → neutral → high hue, with the three anchor values. */
export function DivergingLegend({
  lo,
  mid,
  hi,
  colors,
  format,
  marker,
  width: W = 160,
}: {
  lo: number;
  mid: number;
  hi: number;
  colors: [ChartColor, ChartColor];
  format: (n: number) => string;
  marker: number | null;
  /** Length of the ramp in px. */
  width?: number;
}) {
  const id = useId();
  const reduced = useSheenReducedMotion();
  return (
    <div className="flex flex-nowrap items-center gap-x-2 text-2xs text-sheen-fg-muted">
      <span className="tabular-nums">{format(lo)}</span>
      <span className="relative inline-flex flex-col items-center pb-4">
        <svg
          width={W}
          height={16}
          viewBox={`0 -6 ${W} 16`}
          className="shrink-0 overflow-visible forced-color-adjust-none"
        >
          <defs>
            <linearGradient id={`${id}-d`} x1="0" x2="1" y1="0" y2="0">
              {[-1, -0.66, -0.33, 0, 0.33, 0.66, 1].map((t) => (
                <stop key={t} offset={(t + 1) / 2} style={{ stopColor: divergingColor(t, colors) }} />
              ))}
            </linearGradient>
          </defs>
          <rect width={W} height={10} rx={3} fill={`url(#${id}-d)`} className="forced-colors:stroke-[CanvasText]" />
          <line x1={W / 2} x2={W / 2} y1={-2} y2={12} className="stroke-sheen-fg-subtle" strokeWidth={1} />
          {marker !== null && (
            <motion.path
              d="M-4,-6 L4,-6 L0,-1 Z"
              className="fill-sheen-fg forced-colors:fill-[CanvasText]"
              initial={false}
              animate={{ x: ((clamp(marker, -1, 1) + 1) / 2) * W }}
              transition={reduced ? { duration: 0 } : { duration: duration.fast, ease: ease.out }}
            />
          )}
        </svg>
        <span className="absolute top-full mt-0.5 tabular-nums">{format(mid)}</span>
      </span>
      <span className="tabular-nums">{format(hi)}</span>
    </div>
  );
}

/** Key to bubble sizes: two nested circles (area ∝ value) with their values. */
export function BubbleLegend({
  max,
  maxR,
  color,
  format,
}: {
  max: number;
  maxR: number;
  color: ChartColor;
  format: (n: number) => string;
}) {
  if (!(max > 0)) return null;
  const nice = (v: number) => {
    const p = 10 ** Math.floor(Math.log10(v));
    return Math.max(p, Math.round(v / p) * p);
  };
  const values = [max, nice(max / 4)].filter((v, i, a) => v > 0 && v <= max && a.indexOf(v) === i);
  const rOf = (v: number) => Math.max(3, Math.sqrt(v / max) * maxR);
  const H = Math.max(maxR * 2, 26) + 8; // room above the largest circle for its value
  const base = H - 1;
  // Each value sits level with its circle's top, pushed down so the labels never touch.
  let lastY = -Infinity;
  const marks = values.map((v) => {
    const r = rOf(v);
    const top = base - 2 * r;
    const y = Math.max(top, lastY + 12, 6);
    lastY = y;
    return { v, r, top, y };
  });
  const W = maxR * 2 + 64;
  return (
    <div className="flex items-center text-2xs text-sheen-fg-muted">
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} className="shrink-0 forced-color-adjust-none">
        {marks.map(({ v, r, top, y }) => (
          <g key={v}>
            <circle
              cx={maxR + 1}
              cy={base - r}
              r={r}
              style={{ fill: `color-mix(in oklab, ${slotColor(color)} 22%, transparent)`, stroke: slotColor(color) }}
              strokeWidth={1}
              className="forced-colors:stroke-[CanvasText]"
            />
            <path
              d={`M${maxR + 1},${top}H${maxR * 2 + 4}L${maxR * 2 + 8},${y}`}
              fill="none"
              className="stroke-sheen-fg-subtle"
              strokeDasharray="2 2"
            />
            <text x={maxR * 2 + 12} y={y} dy="0.32em" className="fill-sheen-fg-muted text-2xs tabular-nums">
              {format(v)}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}

/** Height of the band a narrow touch map reserves above itself for the docked readout (two lines). */
export const DOCK_BAND = TOOLTIP_DOCK_SPACE + 18;

/** Wraps text in a first-strong isolate, so numbers and names never reorder inside right-to-left text. */
export const isolate = (text: string) => (text ? `⁨${text}⁩` : text);
/** Formats an easing curve (four numbers) as a CSS `cubic-bezier()`. */
export const cssEase = (e: readonly number[]) => `cubic-bezier(${e.join(",")})`;

/**
 * The reading on a narrow touch map, pinned in the band above it: two fixed lines (the place and
 * its value, then the measure and rank), each truncated, so a long name never spills over the map.
 * Every part is bidi-isolated. Visual only: the map announces the same through ChartAnnouncer.
 */
export function DockedReadout({
  title,
  value,
  color,
  details,
}: {
  title: string;
  value: string;
  color: string | null;
  details: string[];
}) {
  return (
    <div
      aria-hidden
      data-slot="chart-readout"
      className="glass-3 pointer-events-none absolute inset-x-0 top-0 z-10 flex h-12 flex-col justify-center gap-0.5 rounded-sheen-md px-3 text-xs"
    >
      <p className="flex min-w-0 items-center gap-2">
        {color && <LegendKey color={color} />}
        <span dir="auto" className="min-w-0 truncate font-medium text-sheen-fg">
          {title}
        </span>
        <bdi className="ms-auto shrink-0 font-semibold text-sheen-fg tabular-nums">{value}</bdi>
      </p>
      <p dir="auto" className="truncate text-sheen-fg-muted">
        {details.map((part, i) => (
          <span key={i}>
            {i > 0 && " · "}
            <bdi>{part}</bdi>
          </span>
        ))}
      </p>
    </div>
  );
}

/**
 * One bubble, drawn at its place with its zoom-1 radius. It keeps its size on screen while the map
 * zooms through ONE CSS variable on the bubbles' group (--geo-bz = 1 / zoom, a counter-scale), so a
 * zoom frame writes one value, not a radius per bubble. It grows in (and tweens to a new size) with
 * a transform on its own group: no per-frame JS, no geometry attributes.
 */
export function Bubble({
  cx,
  cy,
  r,
  unit,
  color,
  active,
  delay,
  play,
  reduced,
}: {
  cx: number;
  cy: number;
  /** Radius in screen px. */
  r: number;
  /** Frame units per screen px at zoom 1. */
  unit: number;
  color: ChartColor;
  active: boolean;
  delay: number;
  play: boolean;
  reduced: boolean;
}) {
  const growRef = useRef<SVGGElement>(null);
  /** The radius on screen once the last animation settles (null: not shown yet). */
  const shown = useRef<number | null>(null);
  const startDelay = useEffectEvent(() => delay);
  useLayoutEffect(() => {
    const g = growRef.current;
    if (!play || !g) return;
    const prev = shown.current;
    shown.current = r;
    if (reduced || prev === r || typeof g.animate !== "function" || r <= 0) return;
    const anim =
      prev === null
        ? g.animate([{ transform: "scale(0)" }, { transform: "scale(1.06)", offset: 0.7 }, { transform: "none" }], {
            duration: duration.slower * 1000,
            delay: startDelay() * 1000,
            easing: cssEase(ease.out),
            fill: "backwards",
          })
        : g.animate([{ transform: `scale(${prev / r})` }, { transform: "none" }], {
            duration: duration.slow * 1000,
            easing: cssEase(ease.inOut),
          });
    return () => anim.cancel();
  }, [r, play, reduced]);
  const c = slotColor(color);
  return (
    <g transform={`translate(${r1(cx)} ${r1(cy)})`} className="pointer-events-none">
      <g style={{ transform: "scale(var(--geo-bz, 1))", transformOrigin: "0 0" }}>
        <g ref={growRef} style={{ transformOrigin: "0 0" }}>
          {/* A 2px surface ring keeps overlapping bubbles apart (the land still shows through). */}
          <circle
            r={(r + 1.6) * unit}
            fill="none"
            stroke="var(--sheen-chart-surface)"
            strokeWidth={2}
            vectorEffect="non-scaling-stroke"
          />
          <circle
            r={r * unit}
            vectorEffect="non-scaling-stroke"
            strokeWidth={active ? 2 : 1.25}
            className={cn("forced-colors:stroke-[CanvasText]", active && "[filter:var(--geo-glow)]")}
            style={{ fill: `color-mix(in oklab, ${c} ${active ? 88 : 58}%, transparent)`, stroke: c }}
          />
        </g>
      </g>
    </g>
  );
}

/**
 * The country outlines, coloured. Two of these layers stay mounted: a data change writes the new
 * colours into the hidden one and cross-fades (one opacity animation), so no outline is ever
 * created (or its path data parsed) again after the first view.
 */
export function CountryLayer({
  shapes,
  fills,
  count,
  hatch,
  hittable,
  entrance,
}: {
  shapes: readonly WorldCountryShape[];
  /** Fill per shape (null: the "no data" hatch). */
  fills: readonly (string | null)[] | null;
  /** How many outlines to draw (the hidden layer is filled in gradually while the page is idle). */
  count: number;
  hatch: string;
  /** Countries carry data-shape for hit-testing (not in bubble mode). */
  hittable: boolean;
  /** Mark the bands for the first-view wave (data-delay, read by useBandsEntrance). */
  entrance: boolean;
}) {
  const bands = useMemo(() => {
    const out: ReactNode[][] = Array.from({ length: BANDS }, () => []);
    shapes.slice(0, count).forEach((s, i) => {
      const band = clamp(Math.floor((s.c[0] / WORLD_FRAME_WIDTH) * BANDS), 0, BANDS - 1);
      itemAt(out, band).push(
        <path
          key={s.id}
          d={s.d}
          data-shape={hittable ? i : undefined}
          style={{ fill: fills?.[i] ?? (fills ? hatch : LAND) }}
          stroke="var(--sheen-chart-surface)"
          strokeWidth={0.75}
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
          className="forced-colors:stroke-[CanvasText]"
        />,
      );
    });
    return out;
  }, [shapes, fills, count, hatch, hittable]);
  return (
    <g>
      {bands.map((paths, b) => (
        <g key={b} data-delay={entrance ? r1(0.05 + ((b + 0.5) / BANDS) * 0.55) : undefined}>
          {paths}
        </g>
      ))}
    </g>
  );
}

/** Longitude bands of the first-view wave (west to east). */
export const BANDS = 14;

/**
 * The first-view entrance: the land rises in from west to east, one band of longitude after the
 * other. One Web Animation per band (opacity + transform), not per country: cheap to start, and
 * nothing runs per frame in JavaScript. Nothing runs with reduced motion.
 */
export function useBandsEntrance(layerRef: RefObject<SVGGElement | null>, play: boolean, reduced: boolean) {
  const done = useRef(false);
  useLayoutEffect(() => {
    const layer = layerRef.current;
    if (!play || done.current || !layer) return;
    done.current = true;
    if (reduced || typeof layer.animate !== "function") return;
    for (const el of layer.querySelectorAll<SVGGElement>("[data-delay]"))
      el.animate(
        [
          { opacity: 0, transform: "translateY(14px)" },
          { opacity: 1, transform: "none" },
        ],
        {
          duration: duration.slower * 1000,
          delay: Number(el.dataset.delay ?? 0) * 1000,
          easing: cssEase(ease.out),
          fill: "backwards",
        },
      );
  }, [play, reduced, layerRef]);
}

"use client";

import { useEffect, useState } from "react";
import { clamp } from "../chart-utils";
import type { WorldCountryShape } from "../geo/world-110m";

/* ======================================================================
 * Projection: Equal Earth (Šavrič, Patterson & Jenny, 2018), an equal-area
 * projection, so a country's ink is proportional to its real area. The frame
 * must match geo/world-110m.ts (generated with the same constants).
 * ====================================================================== */

/** Size of the map frame (SVG user units). */
export const WORLD_FRAME_WIDTH = 2000;
/**
 * Height of the world map's drawing frame (875 units); the frame is 2000 units wide. The country
 * outlines of `WORLD_110M` are drawn in that frame.
 */
export const WORLD_FRAME_HEIGHT = 875;
/** The northernmost latitude of the drawing frame (degrees). */
export const TOP_LAT = 84;
/** The southernmost latitude of the drawing frame (degrees), which leaves out Antarctica. */
export const BOTTOM_LAT = -58;
/** First coefficient of the Equal Earth projection polynomial. */
export const A1 = 1.340264;
/** Second coefficient of the Equal Earth projection polynomial. */
export const A2 = -0.081106;
/** Third coefficient of the Equal Earth projection polynomial. */
export const A3 = 0.000893;
/** Fourth coefficient of the Equal Earth projection polynomial. */
export const A4 = 0.003796;
/** The Equal Earth constant `sqrt(3) / 2`. */
export const M = Math.sqrt(3) / 2;
/** Units of the map frame per unit of projected x, so the world fills the frame width. */
export const SCALE = WORLD_FRAME_WIDTH / 2 / (Math.PI / (M * A1));

/** The Equal Earth projection of a longitude and latitude (degrees) to unscaled x and y (pure). */
export function equalEarth(lon: number, lat: number): [number, number] {
  const lambda = (lon * Math.PI) / 180;
  const theta = Math.asin(M * Math.sin((lat * Math.PI) / 180));
  const t2 = theta * theta;
  const t6 = t2 * t2 * t2;
  const x = (lambda * Math.cos(theta)) / (M * (A1 + 3 * A2 * t2 + t6 * (7 * A3 + 9 * A4 * t2)));
  const y = theta * (A1 + A2 * t2 + t6 * (A3 + A4 * t2));
  return [x, y];
}

/** The projected y of the top latitude, the origin of the frame's y axis. */
export const Y_TOP = equalEarth(0, TOP_LAT)[1];

/** Longitude / latitude (degrees) to a point in the map frame. Latitudes are clamped to the frame. */
export function projectWorld(lon: number, lat: number): [number, number] {
  const [x, y] = equalEarth(clamp(lon, -180, 180), clamp(lat, BOTTOM_LAT, TOP_LAT));
  return [WORLD_FRAME_WIDTH / 2 + x * SCALE, (Y_TOP - y) * SCALE];
}

/** Rounds to one decimal place (keeps the SVG paths short). */
export const r1 = (n: number) => Math.round(n * 10) / 10;

/** Short, stable hash of a string (FNV-1a), for React keys. */
export function hash(text: string) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(36);
}

/** The sphere's outline inside the frame (left and right edges are the ±180° meridians). */
export const SPHERE_PATH = (() => {
  const left: string[] = [];
  const right: string[] = [];
  for (let lat = TOP_LAT; lat >= BOTTOM_LAT; lat -= 2) {
    const [lx, ly] = projectWorld(-180, lat);
    const [rx, ry] = projectWorld(180, lat);
    left.push(`${r1(lx)},${r1(ly)}`);
    right.unshift(`${r1(rx)},${r1(ry)}`);
  }
  return `M${left.join("L")}L${right.join("L")}Z`;
})();

/** Graticule every 30°: meridians as curves, parallels as straight lines. */
export const GRATICULE_PATH = (() => {
  let d = "";
  for (let lon = -150; lon <= 150; lon += 30) {
    const pts: string[] = [];
    for (let lat = TOP_LAT; lat >= BOTTOM_LAT; lat -= 4) {
      const [x, y] = projectWorld(lon, lat);
      pts.push(`${r1(x)},${r1(y)}`);
    }
    d += `M${pts.join("L")}`;
  }
  for (const lat of [-30, 0, 30, 60]) {
    const [x0, y] = projectWorld(-180, lat);
    const [x1] = projectWorld(180, lat);
    d += `M${r1(x0)},${r1(y)}H${r1(x1)}`;
  }
  return d;
})();

/* ======================================================================
 * Country outlines: loaded on demand (their own ~19 KB gzipped chunk).
 * ====================================================================== */

/** The country outlines once loaded (null until then); shared by every map. */
export let worldCache: readonly WorldCountryShape[] | null = null;
/** The pending load of the country outlines (null before the first load and after a failed one, so a later mount retries). */
export let worldPromise: Promise<readonly WorldCountryShape[]> | null = null;

/** Starts loading the bundled 1:110m world outlines (cached; safe to call repeatedly, e.g. on hover). */
export function loadWorld110m() {
  worldPromise ??= import("../geo/world-110m").then(
    (m) => (worldCache = m.WORLD_110M),
    (error: unknown) => {
      worldPromise = null; // let a later mount retry
      throw error;
    },
  );
  return worldPromise;
}

/** The country outlines to draw: `shapes` when given, else the bundled world, loaded once. */
export function useWorldShapes(shapes: readonly WorldCountryShape[] | undefined) {
  const [loaded, setLoaded] = useState<readonly WorldCountryShape[] | null>(() => worldCache);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    if (shapes || worldCache) return;
    let alive = true;
    loadWorld110m().then(
      (s) => alive && setLoaded(s),
      () => alive && setFailed(true),
    );
    return () => {
      alive = false;
    };
  }, [shapes]);
  return { shapes: shapes ?? loaded ?? worldCache, failed: !shapes && failed };
}

/** "in", "IND", "356", 356 → the key used in the code index. */
export function normalizeCode(code: string | number) {
  const c = String(code).trim().toUpperCase();
  return /^\d+$/.test(c) ? c.padStart(3, "0") : c;
}

/** Index of every alias of each country: alpha-3, alpha-2 and numeric codes. */
export function codeIndex(shapes: readonly WorldCountryShape[]) {
  const map = new Map<string, number>();
  shapes.forEach((s, i) => {
    for (const code of [s.id, s.a2, s.numeric]) if (code) map.set(normalizeCode(code), i);
  });
  return map;
}

/** Cache of `Intl.DisplayNames` by locale (null where the locale is not supported). */
export const regionNames = new Map<string, Intl.DisplayNames | null>();

/**
 * A country's name in `locale` (Intl.DisplayNames), e.g. "Allemagne" for DEU in "fr";
 * Natural Earth's English name when the browser has no name for it.
 */
export function worldCountryName(shape: Pick<WorldCountryShape, "a2" | "name">, locale = "en") {
  let names = regionNames.get(locale);
  if (names === undefined) {
    try {
      names = new Intl.DisplayNames([locale], { type: "region" });
    } catch {
      names = null;
    }
    regionNames.set(locale, names);
  }
  if (names && shape.a2) {
    try {
      const name = names.of(shape.a2);
      if (name && name !== shape.a2) return name;
    } catch {
      /* unknown region code: fall back */
    }
  }
  return shape.name;
}

"use client";

import { useMemo, type ReactNode } from "react";
import { ChartValueTable, defaultCompact, defaultPercent, MissingValue } from "../heatmap";
import { useWorldShapes, normalizeCode, codeIndex, worldCountryName } from "./projection";
import { defaultWorldMapLabels, type WorldMapProps } from "./types";

/* ======================================================================
 * Table view
 * ====================================================================== */

/**
 * Props of WorldMapTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type WorldMapTableProps = Pick<
  WorldMapProps,
  "data" | "points" | "mode" | "format" | "locale" | "valueLabel" | "shapes" | "labels"
> & {
  /** Add a share-of-total column (for additive measures: revenue, users). */
  share?: boolean;
  /** Sets a visually hidden caption that names the table. */
  caption?: string;
  /** Shown when there are no rows. */
  emptyState?: ReactNode;
};

/**
 * Every value on the map as a ranked table: rank, country (or place), value and optional share.
 *
 * Props: the map's `data`, `points`, `mode`, `format`, `locale`, `valueLabel`, `shapes` and `labels`, plus `share` (adds a share column), `caption` (hidden, names the table) and `emptyState`. A real table ranking every value on the map: rank, country (or place) and value. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { WorldMapTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <WorldMapTable data={[{ id: "USA", value: 4200 }, { id: "DEU", value: 1800 }]} valueLabel="Users" share caption="Users by country" />
 *   );
 * }
 * ```
 *
 * @see /charts/world-map
 */
export function WorldMapTable({
  data = [],
  points,
  mode = "choropleth",
  format: formatProp,
  locale = "en",
  valueLabel,
  shapes: shapesProp,
  labels: labelOverrides,
  share = false,
  caption,
  emptyState,
}: WorldMapTableProps) {
  const labels = { ...defaultWorldMapLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const percent = defaultPercent(locale);
  const { shapes } = useWorldShapes(shapesProp);
  const index = useMemo(() => (shapes ? codeIndex(shapes) : new Map<string, number>()), [shapes]);

  const rows = useMemo(() => {
    let list: { name: string; value: number | null }[];
    if (mode === "bubble" && points)
      list = points.map((p) => ({ name: p.label, value: Number.isFinite(p.value) ? p.value : null }));
    else {
      // Exactly what the map draws: codes that match no country are left out (so the ranks agree
      // with the map's "Rank n of N"), and a country given twice keeps its last value, as on the map.
      const byShape = new Map<number, { name: string; value: number | null }>();
      for (const d of data) {
        const i = index.get(normalizeCode(d.id));
        const s = i === undefined ? undefined : shapes?.[i];
        if (i === undefined || !s) continue;
        byShape.set(i, {
          name: d.label ?? worldCountryName(s, locale),
          value: typeof d.value === "number" && Number.isFinite(d.value) ? d.value : null,
        });
      }
      list = [...byShape.values()];
    }
    return list.sort((a, b) => (b.value ?? -Infinity) - (a.value ?? -Infinity) || a.name.localeCompare(b.name, locale));
  }, [data, points, mode, index, shapes, locale]);
  const total = rows.reduce((s, r) => s + (r.value !== null && r.value > 0 ? r.value : 0), 0);

  return (
    <ChartValueTable
      caption={caption}
      emptyState={emptyState ?? labels.noData}
      columns={[
        { label: mode === "bubble" && points ? labels.place : labels.country },
        { label: valueLabel ?? labels.value },
        ...(share ? [{ label: labels.share }] : []),
        { label: labels.rankHeader },
      ]}
      rows={rows.map((r, i) => [
        r.name,
        r.value === null ? <MissingValue label={labels.noData} /> : format(r.value),
        ...(share
          ? [
              r.value === null || total <= 0 ? (
                <MissingValue label={labels.noData} />
              ) : (
                percent(Math.max(0, r.value) / total)
              ),
            ]
          : []),
        r.value === null ? <MissingValue label={labels.noData} /> : String(i + 1),
      ])}
    />
  );
}

import { type ReactNode } from "react";
import { type ChartColor, type ChartInstructions } from "../chart-utils";
import type { WorldCountryShape } from "../geo/world-110m";

/* ======================================================================
 * Types
 * ====================================================================== */

/** A value for one country. `id` is any ISO 3166-1 code: alpha-2 ("IN"), alpha-3 ("IND") or numeric ("356"). */
export type WorldMapDatum = {
  id: string;
  /** null (or missing) reads "No data", never 0. */
  value: number | null;
  /** Name shown instead of the country's own (localised) name. */
  label?: string;
};

/** A bubble at a place (cities, offices, data centres). */
export type WorldMapPoint = {
  /** Stable identity, so the bubble tweens when the data changes. Defaults to the label. */
  id?: string;
  label: string;
  lon: number;
  lat: number;
  value: number;
};

/** What `onSelect` receives. */
export type WorldMapSelection = {
  /** The country's alpha-3 code, or the point's id. */
  id: string;
  name: string;
  value: number | null;
  kind: "country" | "point";
};

/**
 * Every string WorldMap speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type WorldMapLabels = {
  /** Appended to the accessible name: how to read the map with the keyboard (choropleth). */
  instructions: ChartInstructions;
  /** The same for a bubble map, whose items are places rather than countries. */
  instructionsBubble: ChartInstructions;
  /** Role description announced for the map. */
  roleDescription: string;
  /** Tooltip / table text for a country without a value. */
  noData: string;
  /** Legend key for countries without a value. */
  noDataKey: string;
  /** Shown in the readout band of a narrow touch map while nothing is being read (choropleth / bubbles). */
  hint: string;
  hintBubble: string;
  zoomIn: string;
  zoomOut: string;
  resetZoom: string;
  /** Accessible name of the zoom buttons' group; `name` is the map's aria-label. */
  zoomControls: (name: string) => string;
  /** Flashed when someone scrolls over the map without the zoom modifier. `mac` picks ⌘ or Ctrl. */
  zoomHint: (mac: boolean) => string;
  /** Legend caption of a log scale; `caption` is valueLabel. */
  logScale: (caption: string) => string;
  /** "Rank 3 of 42". */
  rank: (rank: number, total: number) => string;
  /** Shown if the map outlines fail to load. */
  loadError: string;
  /** Table headers. */
  rankHeader: string;
  country: string;
  place: string;
  value: string;
  share: string;
};

/**
 * The built-in English strings of WorldMap; spread it into your own `labels` and change what you need.
 * This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultWorldMapLabels: WorldMapLabels = {
  instructions:
    "Arrow keys move to the neighbouring country, Page Up and Page Down step through them by value, Home and End jump to the highest and lowest. Type a name to jump to it. Plus and minus zoom, 0 resets.",
  instructionsBubble:
    "Arrow keys move to the nearest place in that direction, Page Up and Page Down step through them by value, Home and End jump to the highest and lowest. Type a name to jump to it. Plus and minus zoom, 0 resets.",
  roleDescription: "map",
  noData: "No data",
  noDataKey: "No data",
  hint: "Tap a country for its value",
  hintBubble: "Tap a bubble for its value",
  zoomIn: "Zoom in",
  zoomOut: "Zoom out",
  resetZoom: "Reset zoom",
  zoomControls: (name) => `${name}: zoom`,
  zoomHint: (mac) => (mac ? "Use ⌘ + scroll to zoom the map" : "Use Ctrl + scroll to zoom the map"),
  logScale: (caption) => `${caption} (log)`,
  rank: (rank, total) => `Rank ${rank} of ${total}`,
  loadError: "The map could not be loaded.",
  rankHeader: "Rank",
  country: "Country",
  place: "Place",
  value: "Value",
  share: "Share",
};

/**
 * Props of WorldMap. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type WorldMapProps = {
  /** Values by country (choropleth), or bubble sizes at each country's centre (`mode="bubble"`). */
  data?: readonly WorldMapDatum[];
  /** Bubbles at coordinates (cities, offices). Drawn in bubble mode. */
  points?: readonly WorldMapPoint[];
  /** Colour each country by its value, or size a bubble by it. Default "choropleth". */
  mode?: "choropleth" | "bubble";
  /**
   * Choropleth scale: "sequential" (one hue, light → dark: counts, rates) or "diverging"
   * (two hues around a neutral `midpoint`: growth, change, sentiment). Default "sequential".
   */
  scale?: "sequential" | "diverging";
  /** Value at the neutral centre of a diverging scale. Default 0. */
  midpoint?: number;
  /**
   * How values spread over a sequential scale: "linear" (default); "log" for skewed data where one
   * market dwarfs the rest (revenue, population); "quantile" ranks the values, so each colour holds
   * about the same number of countries.
   */
  scaleType?: "linear" | "log" | "quantile";
  /** Hue of the sequential scale and of bubbles: a palette slot 1–8. Default 1. */
  color?: ChartColor;
  /** Hues below and above the midpoint of a diverging scale. Default [2, 7] (orange, blue). */
  divergingColors?: [ChartColor, ChartColor];
  /** The [min, max] the color scale spans; values outside it take the end colors. Default: the data's range (from 0 when every value is positive). */
  domain?: [number, number];
  /** Classes on the scale (e.g. 5); 0 = continuous. */
  steps?: number;
  /** Formats a region's value for the tooltips, legend and data table: takes the number, returns the text shown. Default: compact numbers in `locale`. */
  format?: (n: number) => string;
  /** Locale of the number format and of country names (Intl). Default "en". */
  locale?: string;
  /** Name of the measure (legend caption, tooltip), e.g. "Revenue". */
  valueLabel?: string;
  /** Show the colour (or size) key under the map. Default true. */
  legend?: boolean;
  /** Allow zooming and panning (buttons, ⌘/Ctrl + scroll, pinch, drag, + / −). Default true. */
  zoomable?: boolean;
  /** Deepest zoom level: the map magnifies up to this many times its fitted size. Default 8. */
  maxZoom?: number;
  /** Your own outlines in the same frame (skips loading the bundled world). */
  shapes?: readonly WorldCountryShape[];
  /** Called with a country (or bubble) on click, Enter or Space. */
  onSelect?: (selection: WorldMapSelection) => void;
  /** Shown over the map when there is no data. Default "No data". */
  emptyState?: ReactNode;
  /** Override the chart's strings (i18n). */
  labels?: Partial<WorldMapLabels>;
  /** Names the chart for assistive tech (required). */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

"use client";

import { useCallback, useLayoutEffect, useRef, useState, type RefObject } from "react";
import { animate, useMotionValue } from "motion/react";

import { duration, ease } from "../../motion/tokens";
import { clamp } from "../chart-utils";
import { WORLD_FRAME_HEIGHT, WORLD_FRAME_WIDTH } from "./projection";

/** The map's zoom and pan: a scale `k` and a translation, in frame units. @internal */
export type MapView = { k: number; x: number; y: number };
type View = MapView;

/** What the map's view (zoom / pan) reads. @internal */
export type WorldMapViewInput = {
  /** Frame units per screen px. */
  unit: number;
  ready: boolean;
  mode: string;
  maxZoom: number;
  reduced: boolean;
  /** The zoom groups whose transform is written every frame. */
  zoomRef: RefObject<SVGGElement | null>;
  zoom1Ref: RefObject<SVGGElement | null>;
  zoom2Ref: RefObject<SVGGElement | null>;
};

/**
 * The map's view: motion values written straight to the DOM on every frame (no React render per frame),
 * the committed view, and the animated `setView` / `zoomAt` / `resetView` / `revealPoint` that move it.
 * @internal
 */
export function useWorldMapView(o: WorldMapViewInput) {
  const { unit, ready, mode, maxZoom, reduced, zoomRef, zoom1Ref, zoom2Ref } = o;
  const zk = useMotionValue(1);
  const zx = useMotionValue(0);
  const zy = useMotionValue(0);
  const [view, setViewState] = useState<View>({ k: 1, x: 0, y: 0 });
  /** Where the view is going (equal to the motion values once they settle): zooms chain from here. */
  const target = useRef<View>({ k: 1, x: 0, y: 0 });
  const [moving, setMoving] = useState(false);
  const viewAnim = useRef<{ stop: () => void }[]>([]);
  const hatchRef = useRef<SVGPatternElement>(null);
  const bubblesRef = useRef<SVGGElement>(null);

  // Write the view straight to the DOM on every frame (no React render per frame): the zoom
  // group's transform, the hatch's counter-scale and the bubbles' counter-scale (one variable).
  useLayoutEffect(() => {
    const write = () => {
      const k = zk.get();
      const transform = `translate(${zx.get()} ${zy.get()}) scale(${k})`;
      for (const g of [zoomRef, zoom1Ref, zoom2Ref]) g.current?.setAttribute("transform", transform);
      // The "no data" hatch stays the same fine texture on screen at any zoom.
      hatchRef.current?.setAttribute("patternTransform", `rotate(45) scale(${(unit * 0.8) / k})`);
      bubblesRef.current?.style.setProperty("--geo-bz", String(1 / k));
    };
    write();
    const offs = [zk.on("change", write), zx.on("change", write), zy.on("change", write)];
    return () => offs.forEach((off) => off());
  }, [unit, ready, mode, zk, zx, zy, zoomRef, zoom1Ref, zoom2Ref]);

  const clampView = useCallback(
    (v: View): View => {
      const k = clamp(v.k, 1, Math.max(1, maxZoom));
      return { k, x: clamp(v.x, WORLD_FRAME_WIDTH * (1 - k), 0), y: clamp(v.y, WORLD_FRAME_HEIGHT * (1 - k), 0) };
    },
    [maxZoom],
  );

  const [pointer, setPointer] = useState<{ x: number; y: number } | null>(null);
  const setView = useCallback(
    (next: View, animated = true) => {
      const v = clampView(next);
      target.current = v;
      // A tap's point no longer sits on its place once the view moves: anchor the tooltip to the place.
      setPointer(null);
      viewAnim.current.forEach((a) => a.stop());
      viewAnim.current = [];
      if (!animated || reduced) {
        zk.set(v.k);
        zx.set(v.x);
        zy.set(v.y);
        setViewState(v);
        setMoving(false);
        return;
      }
      setMoving(true);
      const t = { duration: duration.slow, ease: ease.out };
      const done = animate(zk, v.k, t);
      viewAnim.current = [done, animate(zx, v.x, t), animate(zy, v.y, t)];
      void done.then(() => {
        if (target.current !== v) return; // a newer move took over
        setViewState(v);
        setMoving(false);
      });
    },
    [clampView, reduced, zk, zx, zy],
  );

  /**
   * Zoom by `factor`, keeping the frame point under (vx, vy) — in viewBox units — still. It chains
   * from where the view is going, so two quick zooms always land on an exact level (2, 4, 8…).
   */
  const zoomAt = useCallback(
    (factor: number, vx = WORLD_FRAME_WIDTH / 2, vy = WORLD_FRAME_HEIGHT / 2, animated = true) => {
      const { k, x, y } = target.current;
      const nk = clamp(k * factor, 1, maxZoom);
      const px = (vx - x) / k;
      const py = (vy - y) / k;
      setView({ k: nk, x: vx - px * nk, y: vy - py * nk }, animated);
    },
    [maxZoom, setView],
  );

  const resetView = useCallback(() => setView({ k: 1, x: 0, y: 0 }), [setView]);

  /** Pan (animated) so the frame point (x, y) sits in view, centring it if it's off-screen. */
  const revealPoint = useCallback(
    (x: number, y: number) => {
      const { k, x: tx, y: ty } = target.current;
      if (k <= 1) return;
      const sx = x * k + tx;
      const sy = y * k + ty;
      const mx = WORLD_FRAME_WIDTH * 0.12;
      const my = WORLD_FRAME_HEIGHT * 0.12;
      if (sx > mx && sx < WORLD_FRAME_WIDTH - mx && sy > my && sy < WORLD_FRAME_HEIGHT - my) return;
      setView({ k, x: WORLD_FRAME_WIDTH / 2 - x * k, y: WORLD_FRAME_HEIGHT / 2 - y * k });
    },
    [setView],
  );
  return {
    zk,
    zx,
    zy,
    view,
    target,
    moving,
    setMoving,
    setViewState,
    viewAnim,
    hatchRef,
    bubblesRef,
    clampView,
    pointer,
    setPointer,
    zoomAt,
    resetView,
    revealPoint,
  };
}

